@startuml

class Course {
  + name : string
}

class Edition {
  + name : string
}

class Lesson {
  + date : date
  + startTime : time
  + duration : string
}

abstract class Teacher {
  + name : string
}

class InternalTeacher extends Teacher {}

class ExternalTeacher extends Teacher {}

abstract class Participant {}

class MasterStudent extends Participant {}

class ExternalAuditor extends Participant {}

class Room {
  + name : string
}

class Resource {
  + name : string
}

Course "1" -- "0..*" Edition
Course "1" -- "1" InternalTeacher : responsible
Course "0..*" -- "0..*" Teacher : preallocated

Edition "1" *-- "1..*" Lesson
Edition "1" -- "1..*" Participant : enrolled

Lesson "1..*" -- "1..*" Teacher : gives
Lesson "0..*" -- "1" Room
Lesson "0..*" -- "0..*" Resource

@enduml

